#include "common.h"

/* From src/audio.c, to move into include/snd.h with the data split. */
typedef struct SndSe {
    /* 0x0 */ u8 prio;  /* low 5 bits: priority */
    /* 0x1 */ u8 flags; /* high nibble: track - 15 */
    /* 0x2 */ u8 pad2[2];
    /* 0x4 */ u8 *data; /* the commands of its channel, or (several channels) their list */
} SndSe; /* size 0x8 */

typedef struct SndJingle {
    /* 0x0 */ u8 count;
    /* 0x1 */ u8 bank;
    /* 0x2 */ u8 pad2[2];
    /* 0x4 */ u8 **channels;
} SndJingle; /* size 0x8 */

/* Sound effects 0x100-0x1FF: their commands, channel lists and table. */

/* sndse1.c's .data (0x800FAA60-0x80101EC0), in ROM order. */

